package com.spaceagent.platform.inference;

import com.fasterxml.jackson.databind.ObjectMapper;import com.spaceagent.platform.identity.api.*;import com.spaceagent.platform.identity.application.IdentityApplicationService;import com.spaceagent.platform.identity.domain.TenantRole;import com.spaceagent.platform.identity.infrastructure.persistence.PostgresIdentityRepository;import com.spaceagent.platform.inference.api.*;import com.spaceagent.platform.inference.application.*;import com.spaceagent.platform.inference.domain.*;import com.spaceagent.platform.inference.infrastructure.memory.InMemoryModelPoolRepository;import com.spaceagent.platform.inference.infrastructure.persistence.*;import com.spaceagent.shared.id.UuidGenerator;import org.flywaydb.core.Flyway;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import org.testcontainers.containers.PostgreSQLContainer;import org.testcontainers.junit.jupiter.*;import java.sql.Timestamp;import java.time.Instant;import java.util.*;import static org.assertj.core.api.Assertions.*;
@Testcontainers(disabledWithoutDocker=true) class PlatformInferenceBudgetPostgresTest{
 @Container static final PostgreSQLContainer<?> PG=new PostgreSQLContainer<>("pgvector/pgvector:pg17").withDatabaseName("inference_budget").withUsername("spaceagent").withPassword("spaceagent");
 @Test void atomicallyReservesSettlesAndPinsPriceCostToModelCall(){var ds=new DriverManagerDataSource(PG.getJdbcUrl(),PG.getUsername(),PG.getPassword());Flyway.configure().dataSource(ds).locations("classpath:db/platform-server","classpath:db/platform-runtime").load().migrate();var j=new JdbcTemplate(ds);var ids=new UuidGenerator();var identities=new PostgresIdentityRepository(j);var identity=new IdentityApplicationService(identities,ids,Instant::now);String tenant=identity.createTenant(new CreateTenantCommand("Budget","budget-pg")).id(),user=identity.createUser(new CreateUserCommand(tenant,"budget@example.com","Budget")).id();identity.addTenantMembership(new AddTenantMembershipCommand(tenant,user,TenantRole.OWNER));var providers=new PostgresInferenceProviderRepository(j);var pools=new PostgresModelPoolRepository(j);var health=new PostgresProviderHealthProbeRepository(j,new DataSourceTransactionManager(ds),new ObjectMapper());var inference=new InferenceApplicationService(providers,pools,new ModelProviderSecretCipher(){public String encrypt(String v){return "enc:"+v;}public String decrypt(String v){return v.substring(4);}},v->v,ids,Instant::now,health);String provider=inference.createProvider(new CreateModelProviderCommand(tenant,user,"priced","openai-compatible","https://example.com/v1","secret","bearer",true,false,List.of(new CreateModelProviderCommand.ProviderModelDraft("model-a","Model A",32768)))).id();String model=inference.listModels(provider).getFirst().id();var priceRepo=new PostgresModelPriceRepository(j);var price=new ModelPricingApplicationService(priceRepo,providers,ids,Instant::now).createPrice(new ModelPricingApplicationApi.CreatePriceCommand(tenant,user,model,1_000_000,1_000_000,Instant.now().minusSeconds(1),null));String run=UUID.randomUUID().toString(),step=UUID.randomUUID().toString(),agent=UUID.randomUUID().toString();Timestamp now=Timestamp.from(Instant.now());j.update("INSERT INTO platform_agent_definitions(id,owner_id,tenant_id,name,status,revision,created_at,updated_at) VALUES(?,?,?,?,'ACTIVE',1,?,?)",agent,user,tenant,"budget-agent",now,now);j.update("INSERT INTO platform_agent_runs(id,tenant_id,agent_id,owner_id,conversation_id,state,created_at,updated_at) VALUES(?,?,?,?,?,'IN_PROGRESS',?,?)",run,tenant,agent,user,UUID.randomUUID().toString(),now,now);j.update("INSERT INTO platform_run_steps(id,agent_run_id,sequence,type,state,created_at) VALUES(?,?,1,'inference','RUNNING',?)",step,run,now);var budgetRepo=new PostgresInferenceBudgetRepository(j,new DataSourceTransactionManager(ds));var budget=new InferenceBudgetApplicationService(budgetRepo,ids,Instant::now);budget.configure(new InferenceBudgetApplicationApi.ConfigurePolicyCommand(tenant,user,true,1,100,100));var reservation=budget.reserve(new InferenceBudgetApplicationApi.ReserveCommand(tenant,run,step+":call",provider,"model-a",price.id(),1_000_000L,1_000_000L,10,20));var calls=new PostgresModelCallLedgerRepository(j,new DataSourceTransactionManager(ds));var claim=calls.claim(new ModelCallClaimRequest(ids.nextId(),run,step,step+":call","hash",provider,"model-a",UUID.randomUUID().toString(),"worker",60));calls.complete(new ModelCallCompletionRequest(run,step+":call",claim.ledger().claimToken(),claim.ledger().revision(),ModelCallStatus.SUCCEEDED,"provider-request","{\"content\":\"ok\",\"toolCalls\":[]}","{\"inputTokens\":7,\"outputTokens\":3}",null,null));budget.settle(reservation.id(),7,3);assertThat(budget.usage(tenant).consumedCostMicros()).isEqualTo(10);assertThat(j.queryForMap("SELECT price_id::text,input_tokens,output_tokens,cost_micros,cost_currency FROM platform_model_call_ledger WHERE agent_run_id=?",run)).containsEntry("price_id",price.id()).containsEntry("input_tokens",7L).containsEntry("output_tokens",3L).containsEntry("cost_micros",10L).containsEntry("cost_currency","USD");assertThatThrownBy(()->budget.reserve(new InferenceBudgetApplicationApi.ReserveCommand(tenant,UUID.randomUUID().toString(),"second",provider,"model-a",price.id(),1_000_000L,1_000_000L,1,1))).isInstanceOfSatisfying(com.spaceagent.shared.exception.BusinessException.class,e->assertThat(e.getCode()).isEqualTo("INFERENCE_REQUEST_QUOTA_EXCEEDED"));assertThat(j.queryForObject("SELECT count(*) FROM flyway_schema_history WHERE success",Long.class)).isEqualTo(110L);}
}
